export interface CatalogSearchOfferTarget {
    offerId: number;
    pageId: number;
}

export const getCatalogSearchOfferTarget = (furnitureId: number): CatalogSearchOfferTarget | null => {
    const target = CATALOG_SEARCH_OFFER_MAP[furnitureId];

    if (!target) return null;

    return { offerId: target[0], pageId: target[1] };
};
